'use client';

import { useEffect } from 'react';

// Analytics service that logs page views
async function logPageView(page: string, userAgent: string) {
  try {
    // Simulate network request to analytics service
    await fetch('/api/analytics', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify({
        page,
        userAgent,
        timestamp: Date.now(),
      }),
    });
  } catch (error) {
    console.error('Analytics logging failed:', error);
  }
}

// Client component that handles analytics
function AnalyticsTracker() {
  useEffect(() => {
    // Schedule analytics logging after the response is sent
    // This ensures the logging doesn't block the initial page render
    const scheduleAnalytics = () => {
      // Use setTimeout with 0 delay to defer execution until after render
      setTimeout(() => {
        logPageView(window.location.pathname, navigator.userAgent);
      }, 0);
    };

    // Schedule the analytics call
    scheduleAnalytics();
  }, []);

  return null; // This component doesn't render anything visible
}

export default function Home() {
  return (
    <main>
      <h1>Welcome</h1>
      <p>Your page view is being logged asynchronously without blocking the response.</p>
      <AnalyticsTracker />
    </main>
  );
}

