import { NextRequest, NextResponse } from 'next/server';

// Server action to log analytics (runs on server)
export async function POST(request: NextRequest) {
  try {
    const data = await request.json();

    // Simulate logging to an external analytics service
    // In a real app, this would send data to services like Google Analytics, Mixpanel, etc.
    console.log('Analytics event logged:', {
      page: data.page,
      userAgent: data.userAgent,
      timestamp: new Date(data.timestamp).toISOString(),
      source: 'client-side tracking'
    });

    // Simulate network delay for external service
    await new Promise(resolve => setTimeout(resolve, 100));

    return NextResponse.json({ 
      success: true, 
      message: 'Page view logged successfully' 
    });
  } catch (error) {
    console.error('Analytics logging failed:', error);
    return NextResponse.json({ 
      success: false, 
      error: 'Failed to log analytics' 
    }, { status: 500 });
  }
}

// Optional: GET endpoint for debugging
export async function GET() {
  return NextResponse.json({ 
    message: 'Analytics API is working' 
  });
}

// Server component that demonstrates Next.js's recommended approach
// for scheduling work after the response is sent using unstable_after
import { unstable_after } from 'next/server';

// Analytics function that runs on the server
async function logServerAnalytics(page: string, userAgent: string) {
  try {
    // Simulate logging to external analytics service
    console.log('Server-side analytics logged:', {
      page,
      userAgent,
      timestamp: new Date().toISOString(),
      source: 'server-side tracking'
    });

    // Simulate network delay for external service
    await new Promise(resolve => setTimeout(resolve, 100));
  } catch (error) {
    console.error('Server analytics logging failed:', error);
  }
}

export default async function WelcomePage() {
  // Schedule analytics to run after the response is sent
  // This is Next.js's recommended approach for non-blocking server-side work
  unstable_after(logServerAnalytics('/', 'server-component'));

  return (
    <div>
      <h1>Welcome to the Server Component Version</h1>
      <p>Page view logging is scheduled after response using unstable_after()</p>
      <p>This approach ensures analytics don't block the initial page render.</p>
    </div>
  );
}

